__NUXT_JSONP__("/ru/about", (function(a){return {data:[{details:{slug:"ru",pageTitle:"Что такое MLI? | Mentor Language Institute",pageDescription:"Mentor Language Institute был основан в 2002 году и расположен в двух наиболее популярных районах: Вествуд и Голливуд.",section1:{title:"Что такое MLI?",description:["Mentor Language Institute был основан в 2002 году и расположен в двух наиболее популярных районах: Вествуд и Голливуд. Мы помогаем студентам со всего мира улучшить свой английский язык."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Качественные классы за приемлимую цену",description:["Мы ценим две вещи:  \u003Cb\u003E«Качество образования»\u003C\u002Fb\u003E  и  \u003Cb\u003E«Цена».\u003Cb\u003E","Английский - это глобальный язык и необходимый инструмент для общения с людьми со всего мира. Мы надеямся, что международные студенты приобретут необходимые навыки английского языка, чтобы преуспеть в будущем. По этой причине мы концентрируем наше внимание на качестве классов и низкой цене."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"По состоянию на 2020 год более 17 000 студентов выбрали и окончили MLI.",description:["Мы предлагаем ESL (общая программа английского с 6 навыками: грамматика \u002F письмо, чтение \u002F словарный запас и аудирование \u002F речь), TOEFL®, IELTS ™ (для студентов, которые хотят перевестись в колледж) и TOEIC®.","Многие студенты также продолжили обучение в университетах или колледжах США, таких как UCLA, USC и колледже Санта-Моники."],lists:[{link:"\u002Fru\u002Ffeature",image:a,text:"5 причин Почему Люди Выбирают MLI"},{link:"\u002Fru\u002Fcompany",image:a,text:"Информация о компании"},{link:"\u002Fru\u002Fimage-gallery",image:a,text:"Фото \u002F видео галерея"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:28.454Z",updatedAt:"2025-05-26T12:06:27.574Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));